    int32_t pos_y = 0;
    int32_t pos_z = 0;
    uint32_t yaw = 0;
    uint32_t pitch = 0;
    int32_t vel_x = 0;
    int32_t vel_y = 0;
    int32_t vel_z = 0;
    int32_t health = 0;
